app.post("/api/rewrite", async (req, res) => {
  try {
    const { rawReport, senderAddress } = req.body;
    const sender = senderAddress || SIM_ADDR2;
    if (!rawReport) {
      res.status(400).json({ ok: false, error: "rawReport is required" });
      return;
    }
    const rewritten = await rewritePTB(rawReport, sender, "mainnet");
    const q = rewritten.rewrittenQuote ?? rewritten.originalQuote;
    const from = q.fromSymbol ?? rawReport.originalQuote?.fromSymbol ?? "SUI";
    const to = q.toSymbol ?? rawReport.originalQuote?.toSymbol ?? "USDC";
    bumpRegistry("total_rewrites");
    const origScore = rawReport.score ?? 0;
    const rewriteScore = rewritten.score ?? 0;
    const improved = rewriteScore > origScore + 2;
    const origQ = rawReport.originalQuote ?? {};
    const diff = {
      before: {
        score: origScore,
        amountOut: origQ.amountOut ?? "0",
        priceImpact: origQ.priceImpact ?? 0,
        route: (origQ.route ?? []).map((s) => s.protocol)
      },
      after: {
        score: rewriteScore,
        amountOut: q.amountOut ?? "0",
        priceImpact: q.priceImpact ?? 0,
        route: (q.route ?? []).map((s) => s.protocol)
      }
    };
    if (!improved) {
      const reason = rewritten.flags.filter((f) => f.severity !== "green").map((f) => f.title).join(", ") || "route complexity";
      res.json({
        ok: true,
        improved: false,
        message: `This route is already optimal \u2014 ${from}\u2192${to} only has one viable path on Sui. The score of ${origScore}/100 reflects inherent risk from ${reason}, not a bad routing choice. You can still proceed by acknowledging the risk below.`,
        diff
      });
      return;
    }
    res.json({
      ok: true,
      improved: true,
      quote: serializeQuote({ ...q, fromSymbol: from, toSymbol: to }, from, to),
      report: serializeReport(rewritten),
      _rawReport: rewritten,
      diff
    });
  } catch (err) {
    res.status(500).json({ ok: false, error: err instanceof Error ? err.message : String(err) });
  }
});
