app.post("/api/transcribe", async (req, res) => {
  try {
    await new Promise(
      (resolve, reject2) => upload.single("audio")(
        req,
        res,
        (err) => err ? reject2(err) : resolve()
      )
    );
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    res.status(400).json({ ok: false, error: `Upload error: ${msg}` });
    return;
  }
  try {
    if (!req.file) {
      res.status(400).json({ ok: false, error: 'No audio file received. Make sure the field name is "audio".' });
      return;
    }
    const groqKey = process.env.GROQ_API_KEY;
    const openaiKey = process.env.OPENAI_API_KEY;
    if (!groqKey && !openaiKey) {
      res.status(503).json({ ok: false, error: "No transcription API key configured (need GROQ_API_KEY or OPENAI_API_KEY in .env)." });
      return;
    }
    const wallet = req.body.wallet;
    const langHint = req.body.language;
    const lang = langHint || (wallet ? getPreferredLanguage(wallet) : void 0);
    const mimeType = req.file.mimetype || "audio/webm";
    const ext = mimeType.includes("mp4") ? "m4a" : mimeType.includes("ogg") ? "ogg" : mimeType.includes("wav") ? "wav" : "webm";
    let fileBuffer;
    if (req.file.buffer) {
      fileBuffer = req.file.buffer;
    } else if (req.file.stream) {
      const chunks = [];
      for await (const chunk2 of req.file.stream) chunks.push(chunk2);
      fileBuffer = Buffer.concat(chunks);
    } else {
      res.status(500).json({ ok: false, error: "Audio buffer unavailable \u2014 check multer storage config." });
      return;
    }
    if (fileBuffer.length < 100) {
      res.status(400).json({ ok: false, error: "Audio too short or empty." });
      return;
    }
    let transcription;
    if (groqKey) {
      const { default: Groq2, toFile: toFile4 } = await Promise.resolve().then(() => (init_groq_sdk(), groq_sdk_exports));
      const groq = new Groq2({ apiKey: groqKey });
      const audioFile = await toFile4(fileBuffer, `voice.${ext}`, { type: mimeType });
      const result = await groq.audio.transcriptions.create({
        file: audioFile,
        model: "whisper-large-v3-turbo",
        language: lang && lang !== "en" ? lang : void 0,
        response_format: "text"
      });
      transcription = typeof result === "string" ? result : result.text ?? "";
    } else {
      const { default: OpenAI2, toFile: toFile4 } = await Promise.resolve().then(() => (init_openai(), openai_exports));
      const openai = new OpenAI2({ apiKey: openaiKey });
      const audioFile = await toFile4(fileBuffer, `voice.${ext}`, { type: mimeType });
      const result = await openai.audio.transcriptions.create({
        file: audioFile,
        model: "whisper-1",
        language: lang && lang !== "en" ? lang : void 0,
        response_format: "text"
      });
      transcription = typeof result === "string" ? result : result.text ?? "";
    }
    const text = transcription.trim();
    res.json({ ok: true, text });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    res.status(500).json({ ok: false, error: `Transcription failed: ${msg}` });
  }
});
