app.post("/api/echo/:wallet/execute", requireWalletSigOrWorkerSecret(), async (req, res) => {
  try {
    const wallet = req.params.wallet;
    const { from, to, amount } = req.body;
    if (!from || !to || amount == null) {
      res.status(400).json({ ok: false, error: "from, to, amount required" });
      return;
    }
    const fromToken = from.toUpperCase();
    const toToken = to.toUpperCase();
    const { loadSessionKeypair: loadSessionKeypair2 } = await Promise.resolve().then(() => (init_session(), session_exports));
    const keypair = await loadSessionKeypair2(wallet);
    if (!keypair) {
      res.status(400).json({ ok: false, error: "No session key found for wallet" });
      return;
    }
    const data = await readEchoData(wallet);
    const meta = data.sessionKeyMetadata;
    if (!meta) {
      res.status(400).json({ ok: false, error: "No session-key metadata recorded" });
      return;
    }
    if (meta.expiresAt < Date.now()) {
      res.status(400).json({ ok: false, error: "Session key expired" });
      return;
    }
    const sessionAddr = keypair.getPublicKey().toSuiAddress();
    const amountIn = toBaseUnits(amount, fromToken);
    const routex = await createRoutex("mainnet", sessionAddr);
    const quote = await Promise.race([
      routex.getQuote({
        from: fromToken,
        to: toToken,
        amount: amountIn,
        slippageTolerance: 5e-3,
        senderAddress: sessionAddr
      }),
      new Promise(
        (_, reject2) => setTimeout(() => reject2(new Error("Quote timed out")), QUOTE_MS)
      )
    ]);
    const tx = quote.ptb;
    const pkgId = process.env.ECHO_REGISTRY_PACKAGE_ID;
    if (!pkgId) {
      res.status(500).json({
        ok: false,
        error: "ECHO_REGISTRY_PACKAGE_ID not configured \u2014 cannot enforce on-chain limits"
      });
      return;
    }
    const STABLE = /* @__PURE__ */ new Set(["USDC", "USDT", "BUCK"]);
    let usdMicros;
    if (STABLE.has(fromToken)) {
      usdMicros = amountIn;
    } else {
      const px = getCurrentPrice(fromToken);
      if (px == null || !isFinite(px) || px <= 0) {
        res.status(503).json({
          ok: false,
          error: `Cannot derive USD-equivalent for ${fromToken} (no price feed) \u2014 refusing to skip on-chain limit check`
        });
        return;
      }
      usdMicros = BigInt(Math.round(amount * px * 1e6));
    }
    tx.moveCall({
      target: `${pkgId}::session_auth::record_execution`,
      arguments: [
        tx.object(meta.authObjectId),
        tx.pure.u64(usdMicros),
        tx.object("0x6")
      ]
    });
    const sdkClient = await Promise.resolve().then(() => (init_client4(), client_exports));
    const suiClient2 = new sdkClient.SuiClient({ url: sdkClient.getFullnodeUrl("mainnet") });
    const result = await suiClient2.signAndExecuteTransaction({
      signer: keypair,
      transaction: tx,
      options: { showEffects: true }
    });
    res.json({
      ok: true,
      digest: result.digest,
      from: fromToken,
      to: toToken,
      amount
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    res.status(500).json({ ok: false, error: msg });
  }
});
